{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children[p].append(n['id'])
    retained = set(node_map.keys())
    sym_count = {}
    for n in nodes:
        sym = n['symbol']
        sym_count[sym] = sym_count.get(sym, 0) + 1
    removable = [n for n in nodes if n['removable'] and n['id'] != 'root']
    removable.sort(key=lambda x: (-x['depth'], x['id']))
    removed_ids = []
    for node in removable:
        nid = node['id']
        if nid not in retained:
            continue
        if any(cid in retained for cid in children[nid]):
            continue
        subtree_nodes = set()
        stack = [nid]
        while stack:
            cur = stack.pop()
            if cur in subtree_nodes:
                continue
            subtree_nodes.add(cur)
            for c in children[cur]:
                if c in retained:
                    stack.append(c)
        subtree_sym_count = {}
        for sid in subtree_nodes:
            sym = node_map[sid]['symbol']
            subtree_sym_count[sym] = subtree_sym_count.get(sym, 0) + 1
        ok = True
        for sym in required:
            if sym_count.get(sym, 0) - subtree_sym_count.get(sym, 0) <= 0:
                ok = False
                break
        if not ok:
            continue
        for sid in subtree_nodes:
            retained.remove(sid)
            sym = node_map[sid]['symbol']
            sym_count[sym] -= 1
        removed_ids.append(nid)
    retained_ids = sorted(retained)
    return {"removed_node_ids": removed_ids, "retained_node_ids": retained_ids}"
}
